export type SetupCommand={kind:'account';code:string;name:string;accountKind:string}|{kind:'period';start:string;end:string}|{kind:'mappings';expectedVersion:number;components:Record<string,string>};
export type SetupRequest={version:1;actor:string;tenant:string;property:string;request:string;command:SetupCommand};
const uuid=(v:unknown)=>typeof v==='string'&&/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(v);
const day=(v:unknown)=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&Number.isFinite(Date.parse(v))&&new Date(v).toISOString().slice(0,10)===v;
export function validateSetupRequest(value:unknown):SetupRequest{
 if(!value||typeof value!=='object'||Array.isArray(value))throw Error('Invalid retained setup request.');const v=value as SetupRequest,c=v.command;
 if(v.version!==1||Object.keys(v).sort().join(',')!=='actor,command,property,request,tenant,version'||![v.actor,v.tenant,v.property,v.request].every(uuid)||!c||typeof c!=='object')throw Error('Invalid retained setup request.');
 if(c.kind==='account'){if(Object.keys(c).sort().join(',')!=='accountKind,code,kind,name'||typeof c.code!=='string'||! /^[A-Z0-9_-]{1,32}$/.test(c.code)||typeof c.name!=='string'||c.name!==c.name.trim()||c.name.length<1||c.name.length>120||/[\x00-\x1f\x7f]/.test(c.name)||!['asset','liability','equity','income','expense'].includes(c.accountKind))throw Error('Check the account code, name and type.');}
 else if(c.kind==='period'){if(Object.keys(c).sort().join(',')!=='end,kind,start'||!day(c.start)||!day(c.end)||c.start>=c.end)throw Error('Choose a valid accounting period.');}else if(c.kind==='mappings'){if(Object.keys(c).sort().join(',')!=='components,expectedVersion,kind'||!Number.isSafeInteger(c.expectedVersion)||c.expectedVersion<0||c.expectedVersion>=Number.MAX_SAFE_INTEGER||!c.components||typeof c.components!=='object'||Array.isArray(c.components)||!Object.hasOwn(c.components,'receivable')||Object.keys(c.components).length>128||!Object.entries(c.components).every(([k,id])=>(['receivable','accommodation','ota_fee','other_revenue'].includes(k)||/^(tax|fee):[a-z][a-z0-9_]{0,79}$/.test(k))&&uuid(id)))throw Error('Check posting mappings and the current version.');}else throw Error('Unknown setup action.');return v;
}
export function setupKey(actor:string,tenant:string,property:string){if(![actor,tenant,property].every(uuid))throw Error('Verified setup scope required.');return 'iratepilot-pms-gl-setup:'+actor+':'+tenant+':'+property;}
export function readSetupRequest(storage:Pick<Storage,'getItem'>,actor:string,tenant:string,property:string){const raw=storage.getItem(setupKey(actor,tenant,property));if(raw===null)return null;const r=validateSetupRequest(JSON.parse(raw));if(r.actor!==actor||r.tenant!==tenant||r.property!==property)throw Error('Setup request belongs to another scope.');return r;}
export function retainSetupRequest(storage:Pick<Storage,'getItem'|'setItem'>,r:SetupRequest){validateSetupRequest(r);const key=setupKey(r.actor,r.tenant,r.property),raw=JSON.stringify(r),old=storage.getItem(key);if(old!==null&&old!==raw)throw Error('Recover the retained setup request first.');storage.setItem(key,raw);if(storage.getItem(key)!==raw)throw Error('Setup request could not be retained.');}
export function setupParams(r:SetupRequest){validateSetupRequest(r);const c=r.command;return {p_tenant:r.tenant,p_property:r.property,p_request:r.request,p_confirmed:true,...(c.kind==='account'?{p_code:c.code,p_name:c.name,p_kind:c.accountKind}:c.kind==='period'?{p_start:c.start,p_end:c.end}:{p_expected_version:c.expectedVersion,p_mappings:c.components})};}
export function setupReceipt(value:unknown,r:SetupRequest):boolean{
 validateSetupRequest(r);if(!value||typeof value!=='object')return false;const v=value as Record<string,unknown>,c=r.command,item=v[c.kind] as Record<string,unknown>|undefined;
 if(c.kind==='mappings')return v.schema_version===1&&v.tenant_id===r.tenant&&v.property_id===r.property&&v.actor_id===r.actor&&v.request_id===r.request&&v.mapping_id===r.request&&v.version===c.expectedVersion+1&&typeof v.replayed==='boolean';
 return v.schema_version===1&&v.tenant_id===r.tenant&&v.property_id===r.property&&v.actor_id===r.actor&&v.request_id===r.request&&v.kind===c.kind&&typeof v.replayed==='boolean'&&!!item&&item.tenant_id===r.tenant&&item.property_id===r.property&&item.id===r.request&&(c.kind==='account'?item.code===c.code&&item.name===c.name&&item.kind===c.accountKind&&item.active===true:item.starts_on===c.start&&item.ends_before===c.end&&item.closed===false);
}
export function setupStatus(value:unknown,r:SetupRequest):unknown|null{
 if(!value||typeof value!=='object')throw Error('Setup status unavailable.');const v=value as Record<string,unknown>,c=r.command;
 if(v.schema_version!==1||v.tenant_id!==r.tenant||v.property_id!==r.property||v.actor_id!==r.actor||v.request_id!==r.request||typeof v.found!=='boolean')throw Error('Setup status belongs to another request.');
 if(c.kind==='mappings'){
  if(!v.found){if(v.mapping_id!==null||v.version!==null||v.expected_version!==null||v.components!==null)throw Error('Invalid missing mapping response.');return null;}
  if(v.expected_version!==c.expectedVersion||!v.components||typeof v.components!=='object'||Array.isArray(v.components)||Object.keys(v.components).sort().join(',')!==Object.keys(c.components).sort().join(',')||!Object.entries(c.components).every(([k,id])=>(v.components as Record<string,unknown>)[k]===id))throw Error('Saved mapping differs from the retained request.');
  const receipt={...v,replayed:true};if(!setupReceipt(receipt,r))throw Error('Invalid mapping receipt.');return receipt;
 }
 if(!v.found){if(v.kind!==null||v.command!==null||v.result!==null)throw Error('Invalid missing setup response.');return null;}
 const command=c.kind==='account'?{code:c.code,name:c.name,kind:c.accountKind}:{start_date:c.start,end_date_exclusive:c.end};
 if(v.kind!==c.kind||!v.command||typeof v.command!=='object'||Object.keys(v.command).sort().join(',')!==Object.keys(command).sort().join(',')||!Object.entries(command).every(([k,x])=>(v.command as Record<string,unknown>)[k]===x)||!setupReceipt(v.result,r))throw Error('Setup result does not match the retained request.');return v.result;
}
export function clearSetupRequest(storage:Pick<Storage,'getItem'|'removeItem'>,r:SetupRequest,value:unknown){if(!setupReceipt(value,r))throw Error('Setup receipt does not match the retained request.');const key=setupKey(r.actor,r.tenant,r.property);if(storage.getItem(key)!==JSON.stringify(r))throw Error('Retained setup request changed.');storage.removeItem(key);if(storage.getItem(key)!==null)throw Error('Setup request could not be cleared.');}
export function readSetupRetirement(value:unknown,r:SetupRequest):boolean{
 validateSetupRequest(r);if(!value||typeof value!=='object'||Array.isArray(value))throw Error('Setup cancellation result unavailable.');const v=value as Record<string,unknown>;
 if(v.schema_version!==1||v.tenant_id!==r.tenant||v.property_id!==r.property||v.actor_id!==r.actor||v.request_id!==r.request||typeof v.retired!=='boolean'||typeof v.replayed!=='boolean')throw Error('Setup cancellation belongs to another request.');
 if(!v.retired){if(v.command!==null||v.retired_at!==null)throw Error('Invalid missing setup cancellation.');return false;}
 const canonical=(x:unknown):string=>{if(x&&typeof x==='object'&&!Array.isArray(x))return JSON.stringify(Object.keys(x).sort().map(k=>[k,canonical((x as Record<string,unknown>)[k])]));return JSON.stringify(x);};
 if(canonical(v.command)!==canonical(r.command)||typeof v.retired_at!=='string'||!Number.isFinite(Date.parse(v.retired_at)))throw Error('Cancelled setup does not match the retained details.');return true;
}
export function clearSetupRetirement(storage:Pick<Storage,'getItem'|'removeItem'>,r:SetupRequest,value:unknown){if(!readSetupRetirement(value,r))throw Error('Setup cancellation is not saved.');const key=setupKey(r.actor,r.tenant,r.property);if(storage.getItem(key)!==JSON.stringify(r))throw Error('Retained setup request changed.');storage.removeItem(key);if(storage.getItem(key)!==null)throw Error('Cancelled setup could not be cleared.');}
